let alphabetsData = null;
let optionsData = null;

export async function loadAlphabets() {
  if (alphabetsData) return alphabetsData;

  const response = await fetch('./benchmark-data/alphabets.json');
  alphabetsData = await response.json();
  return alphabetsData;
}

export async function loadMultipleChoiceOptions() {
  if (optionsData) return optionsData;

  const response = await fetch('./benchmark-data/multiple-choice-options.json');
  optionsData = await response.json();
  return optionsData;
}

export function getAlphabet(alphabetName) {
  if (!alphabetsData) {
    throw new Error('Alphabets not loaded. Call loadAlphabets() first.');
  }
  return alphabetsData[alphabetName];
}

export function getOptions(alphabetName, symbol) {
  if (!optionsData) {
    throw new Error('Options not loaded. Call loadMultipleChoiceOptions() first.');
  }
  return optionsData[alphabetName]?.[symbol] || [];
}
