import { t, setLanguage, getLanguage } from './i18n.js';
import { loadAlphabets, loadMultipleChoiceOptions, getAlphabet, getOptions } from './data.js';

// Application State
const state = {
  alphabet: 'polish',
  mode: 'keyboard',
  currentSymbols: [],
  currentIndex: 0,
  hintedQuestions: new Set(),
  isActive: false
};

// DOM Elements
let setupScreen, exerciseScreen, resultScreen, attributionEl;

function initDOMReferences() {
  setupScreen = document.getElementById('setup-screen');
  exerciseScreen = document.getElementById('exercise-screen');
  resultScreen = document.getElementById('result-screen');
  attributionEl = document.getElementById('attribution');
}

// Utility Functions
function shuffleArray(array) {
  const shuffled = [...array];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }
  return shuffled;
}

function showScreen(screen) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  screen.classList.add('active');
}

// Setup Screen
function initSetupScreen() {
  const languageSelect = document.getElementById('language-select');
  const startBtn = document.getElementById('start-btn');

  languageSelect.addEventListener('change', (e) => {
    setLanguage(e.target.value);
    updateUILanguage();
  });

  startBtn.addEventListener('click', startExercise);

  updateUILanguage();
}

function updateUILanguage() {
  document.getElementById('title').textContent = t('title');
  document.getElementById('label-language').textContent = t('labelLanguage');
  document.getElementById('label-alphabet').textContent = t('labelAlphabet');
  document.getElementById('label-mode').textContent = t('labelMode');

  // Update alphabet select options
  const alphabetSelect = document.getElementById('alphabet-select');
  alphabetSelect.options[0].text = t('polish');
  alphabetSelect.options[1].text = t('nato');

  // Update mode select options
  const modeSelect = document.getElementById('mode-select');
  modeSelect.options[0].text = t('keyboardMode');
  modeSelect.options[1].text = t('suggestionMode');

  document.getElementById('start-btn').textContent = t('start');
}

// Exercise Logic
async function startExercise() {
  const alphabetSelect = document.getElementById('alphabet-select');
  const modeSelect = document.getElementById('mode-select');

  state.alphabet = alphabetSelect.value;
  state.mode = modeSelect.value;
  state.currentIndex = 0;
  state.hintedQuestions = new Set();
  state.isActive = true;

  // Load data
  const alphabet = await loadAlphabets();
  state.currentSymbols = shuffleArray(alphabet[state.alphabet]);

  // Disable language selection during active run (decision: not allowed during run)
  document.getElementById('language-select').disabled = true;

  showScreen(exerciseScreen);
  showCurrentQuestion();
}

function showCurrentQuestion() {
  const symbol = state.currentSymbols[state.currentIndex];
  const total = state.currentSymbols.length;
  const current = state.currentIndex + 1;

  // Update progress
  document.getElementById('progress-info').textContent = t('progress', { current, total });

  // Display symbol
  document.getElementById('symbol-display').textContent = symbol.symbol;

  // Reset hint display
  document.getElementById('hint-display').classList.add('hidden');
  document.getElementById('hint-display').textContent = '';

  // Reset feedback
  document.getElementById('feedback').textContent = '';
  document.getElementById('feedback').className = '';

  // Show correct input mode
  const keyboardInput = document.getElementById('keyboard-input');
  const suggestionInput = document.getElementById('suggestion-input');

  if (state.mode === 'keyboard') {
    keyboardInput.classList.add('active');
    suggestionInput.classList.remove('active');
    setupKeyboardMode();
  } else {
    keyboardInput.classList.remove('active');
    suggestionInput.classList.add('active');
    setupSuggestionMode(symbol);
  }

  // Update hint button
  document.getElementById('hint-btn').textContent = t('hint');
}

// Keyboard Mode
function setupKeyboardMode() {
  const input = document.getElementById('answer-input');
  const submitBtn = document.getElementById('submit-btn');

  input.value = '';
  input.placeholder = t('typeAnswer');
  submitBtn.textContent = t('submit');

  // Remove old listeners by cloning
  const newInput = input.cloneNode(true);
  input.parentNode.replaceChild(newInput, input);

  const newSubmitBtn = submitBtn.cloneNode(true);
  submitBtn.parentNode.replaceChild(newSubmitBtn, submitBtn);

  newInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      handleKeyboardSubmit();
    }
  });

  newSubmitBtn.addEventListener('click', handleKeyboardSubmit);
}

async function handleKeyboardSubmit() {
  const input = document.getElementById('answer-input');
  const answer = input.value;
  const currentSymbol = state.currentSymbols[state.currentIndex];
  const correctAnswer = currentSymbol.codeword;

  if (checkAnswer(answer, correctAnswer)) {
    showFeedback(t('correct'), 'correct');
    input.value = '';
    setTimeout(() => {
      nextQuestion();
    }, 500);
  } else {
    showFeedback(t('incorrect'), 'incorrect');
  }
}

// Suggestion Mode
async function setupSuggestionMode(symbol) {
  const buttonsContainer = document.getElementById('suggestion-buttons');
  buttonsContainer.innerHTML = '';

  const options = getOptions(state.alphabet, symbol.symbol);

  if (!options || options.length === 0) {
    console.error('No options found for symbol:', symbol.symbol);
    return;
  }

  // Shuffle the options
  const shuffledOptions = shuffleArray(options);

  shuffledOptions.forEach(option => {
    const button = document.createElement('button');
    button.className = 'suggestion-btn';
    button.textContent = option;
    button.addEventListener('click', () => handleSuggestionClick(option, symbol.codeword));
    buttonsContainer.appendChild(button);
  });
}

async function handleSuggestionClick(selected, correct) {
  if (selected === correct) {
    showFeedback(t('correct'), 'correct');
    setTimeout(() => {
      nextQuestion();
    }, 500);
  } else {
    showFeedback(t('incorrect'), 'incorrect');
  }
}

// Answer Checking
function checkAnswer(answer, correctAnswer) {
  if (!answer) return false;

  // Trim whitespace and compare case-insensitive
  const trimmed = answer.trim();
  return trimmed.toLowerCase() === correctAnswer.toLowerCase();
}

// Feedback
function showFeedback(message, type) {
  const feedback = document.getElementById('feedback');
  feedback.textContent = message;
  feedback.className = type;
}

// Hint Functionality
function initHintButton() {
  const hintBtn = document.getElementById('hint-btn');
  hintBtn.addEventListener('click', showHint);
}

function showHint() {
  const currentSymbol = state.currentSymbols[state.currentIndex];
  const hintDisplay = document.getElementById('hint-display');

  // Mark this question as hinted
  state.hintedQuestions.add(state.currentIndex);

  // Show the correct answer
  hintDisplay.textContent = `Hint: ${currentSymbol.codeword}`;
  hintDisplay.classList.remove('hidden');

  // In suggestion mode, don't highlight the correct button
  // The hint just shows the text (requirement: not auto-select or auto-submit)
}

// Navigation
function nextQuestion() {
  state.currentIndex++;

  if (state.currentIndex >= state.currentSymbols.length) {
    finishExercise();
  } else {
    showCurrentQuestion();
  }
}

// Result Screen
function finishExercise() {
  state.isActive = false;

  // Enable language selection again
  document.getElementById('language-select').disabled = false;

  const total = state.currentSymbols.length;
  const hinted = state.hintedQuestions.size;
  const clean = total - hinted;
  const score = Math.round((clean / total) * 100);

  // Update result screen
  document.getElementById('result-title').textContent = t('resultTitle');
  document.getElementById('result-score').textContent = `${t('resultScore')} ${score}%`;
  document.getElementById('result-details').innerHTML = `
    ${t('resultAlphabet')} ${t(state.alphabet)}<br>
    ${t('resultMode')} ${state.mode === 'keyboard' ? t('keyboardMode') : t('suggestionMode')}
  `;
  document.getElementById('restart-btn').textContent = t('restart');

  showScreen(resultScreen);
}

function initRestartButton() {
  const restartBtn = document.getElementById('restart-btn');
  restartBtn.addEventListener('click', () => {
    showScreen(setupScreen);
  });
}

// Initialize App
async function init() {
  initDOMReferences();
  initSetupScreen();
  initHintButton();
  initRestartButton();

  // Load data on startup
  await Promise.all([loadAlphabets(), loadMultipleChoiceOptions()]);

  console.log('Phonetic Benchmark v2 initialized');
}

// Start the app
init();
